ALTER TABLE public.products ADD COLUMN IF NOT EXISTS hidden boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS supplier_name text, ADD COLUMN IF NOT EXISTS estimated_price boolean NOT NULL DEFAULT false;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS fulfillment_status text NOT NULL DEFAULT 'placed', ADD COLUMN IF NOT EXISTS estimated_delivery text;
ALTER TABLE public.order_items ADD COLUMN IF NOT EXISTS image_url text;
CREATE TABLE public.admin_access (identity text PRIMARY KEY, role text NOT NULL DEFAULT 'admin');
GRANT ALL ON public.admin_access TO service_role;
ALTER TABLE public.admin_access ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_access (user_id uuid PRIMARY KEY, blocked boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.user_access TO authenticated;
GRANT ALL ON public.user_access TO service_role;
ALTER TABLE public.user_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own account access" ON public.user_access FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.store_settings (id text PRIMARY KEY DEFAULT 'store', shop_name text NOT NULL DEFAULT 'ShopArena NG', whatsapp text NOT NULL DEFAULT '2348089778840', delivery_fees jsonb NOT NULL DEFAULT '{"Ikeja":2000,"Lekki":2500,"Surulere":2000,"Yaba":1800,"Ikorodu":3500,"Ajah":3000}');
GRANT SELECT ON public.store_settings TO authenticated;
GRANT ALL ON public.store_settings TO service_role;
ALTER TABLE public.store_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Customers read store settings" ON public.store_settings FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS "Anyone can view products" ON public.products;
CREATE POLICY "Members browse visible products" ON public.products FOR SELECT TO authenticated USING (NOT hidden AND NOT EXISTS (SELECT 1 FROM public.user_access WHERE user_id = auth.uid() AND blocked));
DROP POLICY IF EXISTS "Public bank transfer details" ON public.bank_settings;
CREATE POLICY "Members read bank transfer details" ON public.bank_settings FOR SELECT TO authenticated USING (true);
GRANT SELECT ON public.orders TO authenticated;
CREATE POLICY "Customers read own orders" ON public.orders FOR SELECT TO authenticated USING (user_id = auth.uid() AND NOT EXISTS (SELECT 1 FROM public.user_access WHERE user_id = auth.uid() AND blocked));
ALTER PUBLICATION supabase_realtime ADD TABLE public.orders;